//! Embedded guest ELF and image ID generated by `risc0-build`.

include!(concat!(env!("OUT_DIR"), "/methods.rs"));

/// How the embedded guest was built.
///
/// `"docker"` means RISC Zero's reproducible builder image
/// (`ZKML_GUEST_DOCKER=1`), whose image id is the same on every machine and is
/// the one to register on chain. `"local"` means the host toolchain, whose
/// image id differs between machines.
pub const ZKML_GUEST_BUILD: &str = env!("ZKML_GUEST_BUILD");
